rate=1200000/(temp[20]-temp[0]);//60*20*1000/20_total_time \n          Serial.print("Heart_rate_is:\\t");\n          Serial.println(heart_rate);\n        }\n       data_effect=1;//sign bit\n    }\n    /*Function: Interrupt service routine.Get the sigal from the external interrupt*/\n    void interrupt()\n    {\n        temp[counter]=millis();\n        Serial.println(counter,DEC);\n        Serial.println(temp[counter]);\n        switch(counter)\n        {\n            case 0:\n                sub=temp[counter]-temp[20];\n                Serial.println(sub);\n                break;\n            default:\n                sub=temp[counter]-temp[counter-1];\n                Serial.println(sub);\n                break;\n        }\n        if(sub>max_heartpluse_duty)//set 2 seconds as max heart pluse duty\n        {\n            data_effect=0;//sign bit\n            counter=0;\n            Serial.println("Heart rate measure error,test will restart!" );\n            arrayInit();\n        }\n        if (counter==20&&data_effect)\n        {\n            counter=0;\n            sum();\n        }\n        else if(counter!=20&&data_effect)\n        counter++;\n        else \n        {\n            counter=0;\n            data_effect=1;\n        }\n        \n    }\n    /*Function: Initialization for the array(temp)*/\n    void arrayInit()\n    {\n        for(unsigned char i=0;i < 20;i ++)\n        {\n            temp[i]=0;\n        }\n        temp[20]=millis();\n    }\n'})}),"\n",(0,s.jsxs)(r.ul,{children:["\n",(0,s.jsx)(r.li,{children:"Sube el c\xf3digo."}),"\n",(0,s.jsx)(r.li,{children:"Esta es la se\xf1al cuando estamos midiendo la frecuencia card\xedaca:"}),"\n"]}),"\n",(0,s.jsx)("div",{align:"center",children:(0,s.jsx)("img",{width:1e3,src:"https://files.seeedstudio.com/wiki/Grove-Chest_Strap_Heart_Rate_Sensor/img/GROVE_heart_rate_chest_belt.bmp"})}),"\n",(0,s.jsx)("div",{align:"center",children:(0,s.jsx)("img",{width:1e3,src:"https://files.seeedstudio.com/wiki/Grove-Chest_S